<script setup>
import {inject, onMounted, ref} from 'vue'
import { useLocale } from 'vuetify'
import Vuedraggable from 'vuedraggable'
import { weekApi, weekToolApi} from '@/service/api'
import { hasTouchScreen } from '@/plugins/constants'
import { useUserStore } from '@/plugins/store'
import * as Nav from '@/service/nav'
import CourseDetailLessonRow from '@/components/course/CourseDetailLessonRow.vue'
import TooltipIconButton from '@/components/custom/TooltipIconButton.vue'
import CourseDetailToolRow from "@/components/course/CourseDetailToolRow.vue";

const appState = inject('appState')
const courseUser = inject('courseUser')
const userStore = useUserStore()
const { current, t } = useLocale()
const props = defineProps(['week', 'isTeacher'])

const deleteDialog = inject('deleteDialog')
const createEditDialog = inject('createEditDialog')
const copyDialog = inject('copyDialog')
const toolAddDialog = inject('toolAddDialog')
const deleteLesson = inject('deleteLessonEntity')
const deleteWeek = inject('deleteWeekEntity')
const editWeek = inject('editWeekEntity')
const copyTargetWeekId = inject('copyTargetWeekId')

const combinedItems = ref([])

const weekNameRef = ref(null)
const isTruncated = ref(false)

const checkTruncation = () => {
  if (weekNameRef.value) {
    isTruncated.value = weekNameRef.value.scrollWidth > weekNameRef.value.clientWidth
  }
}

const translate = (x, param = undefined) => t(`$vuetify.course_detail_week_lesson_order_changed_${x}`, param)


const moveCombined = (e) => {
  if (e.removed) return // ignore change
  weekApi.editWeekItemsOrder(props.week.id, combinedItems.value.map((i) => i.id))
      .then(() => { appState.value.notifications.push({
        type: "success", title: translate('title'), text: translate('text')
      }) })
      .catch((err) => { appState.value.notifications.push({
        type: "error", title: translate('error_title'), text: translate('error_text', err.code)
      }) })
}

onMounted(async () => {
  // Load week items
  // gets only [id:int, type:enum, order:int]
  const rawItems = await weekApi.getWeekItems(props.week.id)
  // Small amount of data
  // Gets [id:int, name:string, url:string] for corresponding week
  const allToolsInWeek = await weekToolApi.getToolsByWeekId(props.week.id)

  combinedItems.value = rawItems.map(item => {
    if (item.type === 'TOOL') {
      // find tool object by id
      const tool = allToolsInWeek.find(t => t.id === item.id)
      return { ...item, tool }
    }

    if (item.type === 'LESSON') {
      // find lesson object by id
      // already contains a lesson object in this component, we do not fetch it again
      const lesson = props.week.lessons.find(l => l.id === item.id)
      return { ...item, lesson }
    }

    return item
  })

})

</script>

<template>
  <tr style="cursor: pointer" @click="userStore.hiddenWeeks[week.id] = !userStore.hiddenWeeks[week.id]">
    <th v-ripple.center colspan="5" scope="row">
      <div class="d-flex align-center w-100 ga-4" style="height: 48px;">
        <v-btn variant="text" density="compact" :icon="userStore.hiddenWeeks[week.id] ? 'mdi-chevron-down' : 'mdi-chevron-up'" />
        <div class="d-flex align-center ga-2" style="width: 50%; max-width: 50%; min-width: 50%;">
          <span ref="weekNameRef" class="text-truncate pl-4" style="min-width: 0;"
                @mouseenter="checkTruncation">
            {{ week.name }}
            <v-tooltip v-if="isTruncated" activator="parent" location="bottom start" :offset="-3" transition="scale-transition">
              {{ week.name }}
            </v-tooltip>
          </span>
          <span v-if="userStore.anonymous && week.lessons.some((l) => l.hidden)" class="font-weight-regular flex-shrink-0">
            ({{ week.lessons.filter((l) => l.hidden).length }} 👻)
            <v-tooltip activator="parent" location="top">{{ t('$vuetify.hidden_lesson_count') }}</v-tooltip>
          </span>
        </div>
        <span class="flex-grow-1 text-center">
          {{ new Date(week.from).toLocaleDateString(current === 'customCs' ? 'cs' : 'en') }}
          –
          {{ new Date(week.until).toLocaleDateString(current === 'customCs' ? 'cs' : 'en') }}
        </span>
        <span v-if="isTeacher && !userStore.anonymous" class="d-flex flex-shrink-0">
          <TooltipIconButton icon="mdi-delete"
                             @click="(e) => { e.stopPropagation(); deleteLesson = null; deleteWeek = week; deleteDialog = true }" />
          <TooltipIconButton icon="mdi-pencil"
                             @click="(e) => { e.stopPropagation(); editWeek = week; createEditDialog = true }" />
        </span>
      </div>
    </th>
  </tr>
  <Vuedraggable
    v-show="!userStore.hiddenWeeks[week.id]"
    tag="tbody"
    item-key="id"
    :disabled="!isTeacher || courseUser"
    group="combined"
    :list="combinedItems"
    :handle="hasTouchScreen() ? '.handle-btn' : '.handle-row'"
    @change="moveCombined"
  >
    <template #item="{ element }">
      <component
        :is="element.type === 'TOOL' ? CourseDetailToolRow : CourseDetailLessonRow"
        v-if="!userStore.anonymous || (element.type === 'LESSON' ? !element.lesson.hidden : true)"
        class="handle-row"
        :tool="element.type === 'TOOL' ? element.tool : undefined"
        :lesson="element.type === 'LESSON' ? element.lesson : undefined"
        :week="element.type === 'TOOL' ? week : undefined"
      />
    </template>
  </Vuedraggable>
  <v-card-actions v-if="isTeacher && !userStore.anonymous" v-show="!userStore.hiddenWeeks[week.id]">
    <v-btn variant="tonal" density="comfortable" class="ml-3 text-primary"
           :to="new Nav.LessonCreate(week).routerPath()">
      {{ t('$vuetify.course_detail_header_new_lesson') }}
    </v-btn>
    <v-btn variant="tonal" density="comfortable" class="ml-5 text-primary"
           @click="copyTargetWeekId = week.id; copyDialog = true">
      {{ t('$vuetify.course_detail_lesson_copy_title') }}
    </v-btn>
    <v-btn variant="tonal" density="comfortable" class="ml-5 text-primary"
           @click="copyTargetWeekId = week.id; toolAddDialog = true">
      {{ t('$vuetify.course_detail_tool_add_title') }}
    </v-btn>
  </v-card-actions>
</template>
