<script setup>
import {toolApi, weekToolApi} from '@/service/api'
import {inject, onMounted, ref, watch} from "vue";
import {useLocale} from "vuetify";
import TooltipIconButton from "@/components/custom/TooltipIconButton.vue";
import {diacriticInsensitiveStringIncludes} from "@/plugins/constants";
import LoadingScreen from "@/components/custom/LoadingScreen.vue";

const appState = inject('appState')
const props = defineProps(['targetWeekId', 'targetCourseId', 'callback'])

const toolAddDialog = inject('toolAddDialog')

const {t} = useLocale()
const translate = (key) => t(`$vuetify.course_detail_tool_add_${key}`)
const addableItems = ref(null)
const existingWeekTools = ref(null)


const addTool = (toolId) => {
  weekToolApi.putWeekTool(toolId, props.targetWeekId).then(() => {
    appState.value.notifications.push({
      type: "success", title: translate('success_title'), text: translate(`success_text`)
      });
    existingWeekTools.value[toolId] = true
    props.callback();
  })
}

const search = ref({
  name: "",
})

const searchFilter = (item) => {
  return (!search.value.name.length || diacriticInsensitiveStringIncludes(item.name.toLowerCase(), search.value.name.toLowerCase()))
}

const resetDialog = async () => {
  search.value.name = ""

  addableItems.value = null

  try {
    const result = await toolApi.listAll()
    addableItems.value = result
    console.log(addableItems.value)
  } catch (err) {
    console.error('API error:', err)
    addableItems.value = []
  }

  if (props.targetWeekId) {
    await loadWeekTools(props.targetWeekId)
  }
}



async function loadWeekTools(weekId) {
  existingWeekTools.value = {}

  const tools = await weekToolApi.getToolsByWeekId(weekId)
  console.log("tools",tools)
  console.log(existingWeekTools.value)
  for (const t of tools) {
    existingWeekTools.value[t.id] = true
  }
}

function isEnabled(toolId) {
  if (existingWeekTools.value === null) return false
  return !existingWeekTools.value[toolId]
}

onMounted(async () => {
  await resetDialog();
})

watch(props, resetDialog)

watch(toolAddDialog, async (newValue) => {
  if (newValue) {
    await resetDialog()
  }
})

</script>

<template>
  <v-dialog v-model="toolAddDialog" width="80%" height="100%">
    <v-card :title="translate('title')">
      <LoadingScreen :items="addableItems">
        <template #content>
          <div class="d-flex justify-start  ga-4">
            <v-text-field v-model="search.name" :style="targetWeekId ? {'flex': '0 0 40%'} : {'flex': '0 0 47%'}"
                          :label="t('$vuetify.course_detail_copy_search_name')" />
          </div>
          <template v-for="item in addableItems.filter(searchFilter)" :key="item.id">
            <div style="display: grid; grid-template-columns: 1fr 1fr 1fr 1fr; text-align: left; align-items: center; padding: 8px 24px; border-bottom: thin #00000020 solid">
              <template v-if="targetWeekId">
                <span v-if="targetWeekId" style="grid-column: 1">
                  <v-icon class="mr-2" size="18" icon="mdi-tools" />
                  <strong>{{ `${item.name}` }}</strong>
                </span>
              </template>
              <TooltipIconButton icon="mdi-plus" style="grid-column: 4; justify-self: end"
                                 :color="isEnabled(item.id) ? 'rgb(var(--v-theme-anchor))' : 'grey'" :tooltip="isEnabled(item.id) ? translate('title') : translate('disabled_title')"
                                 @click="isEnabled(item.id) ? addTool(item.id) : null" />
            </div>
          </template>
          <span v-if="addableItems.filter(searchFilter).length === 0" style="padding: 0 24px 16px 24px">
            {{ translate('no_matches') }}
          </span>
        </template>
      </LoadingScreen>
    </v-card>
    <!-- height 100% fixes the dialog to the top, but creates an invisible area below that otherwise wouldn't dismiss it -->
    <div style="flex: 1" @click="() => toolAddDialog = false" />
  </v-dialog>
</template>