<script setup>
import { inject } from 'vue'
import {weekToolApi} from '@/service/api'
import { useLocale } from 'vuetify'
import { getErrorMessage } from '@/plugins/constants'

const appState = inject('appState')
const props = defineProps(['week', 'tool', 'callback'])
const deleteToolDialog = inject('deleteToolDialog')
const { t } = useLocale()

const translate = (key) => t(`$vuetify.course_detail_tool_delete_${key}`)
const deleteCallback = (weekId,toolId) => {
  deleteToolDialog.value = false
  const promise = weekToolApi.deleteWeekTool(weekId,toolId)
  promise
      .then(() => {
        appState.value.notifications.push({
          type: "success", title: translate('success_title'), text: translate('success_text')
        })
        props.callback()
      })
      .catch((err) => {
        appState.value.notifications.push({
          type: "error", title: t(`$vuetify.error_deleting_tool`),
          text: getErrorMessage(t, err.code)
        })
      })
}
</script>

<template>
  <v-dialog v-model="deleteToolDialog" width="auto" @keydown.enter="deleteCallback(week, tool.id)">
    <v-card :title="translate('title')">
      <v-card-item class="text-center" :style="{'white-space': 'pre-line'}">
        {{ translate('confirm_p1') }}<strong>{{ tool.name }}</strong>{{ translate('confirm_p2') }}
      </v-card-item>
      <v-card-actions>
        <div style="width: 100%" class="d-flex flex-row justify-space-between pa-2">
          <v-btn color="primary" @click="deleteToolDialog = false">
            {{ t('$vuetify.dialog_close') }}
          </v-btn>
          <v-btn color="red" @click="deleteCallback(week, tool.id)">
            {{ t('$vuetify.action_delete') }}
          </v-btn>
        </div>
      </v-card-actions>
    </v-card>
  </v-dialog>
</template>
